# Team class
class Team:
    def __init__(self, name, logo):
        self.name = name
        self.logo = logo
        self.players = []

    def add_player(self, player):
        self.players.append(player)

    def remove_player(self, player):
        self.players.remove(player)

# Player class
class Player:
    def __init__(self, name, position, skills):
        self.name = name
        self.position = position
        self.skills = skills

    def update_skills(self, skills):
        self.skills = skills

# Match class
class Match:
    def __init__(self, team1, team2):
        self.team1 = team1
        self.team2 = team2
        self.score = 0

    def simulate_match(self):
        # Simulate the match and update the score
        self.score = 10

# Strategy class
class Strategy:
    def __init__(self, team):
        self.team = team

    def develop_strategy(self):
        # Develop a strategy for the team
        print("Developing strategy for team", self.team.name)

# Factory class
class TeamFactory:
    def create_team(self, name, logo):
        return Team(name, logo)

    def create_player(self, name, position, skills):
        return Player(name, position, skills)

# Observer class
class Observer:
    def update(self, team):
        # Notify the team of changes in the game state
        print("Notifying team", team.name, "of changes in the game state")

# Usage
factory = TeamFactory()
team1 = factory.create_team("Team1", "Logo1")
team2 = factory.create_team("Team2", "Logo2")

player1 = factory.create_player("Player1", "Position1", ["Skill1", "Skill2"])
player2 = factory.create_player("Player2", "Position2", ["Skill3", "Skill4"])

team1.add_player(player1)
team2.add_player(player2)

match = Match(team1, team2)
match.simulate_match()

strategy = Strategy(team1)
